import{_ as e,o as n,c as r,a as t}from"./app.1d37f686.js";var i="/aktivitaeten/bunkerfest2026/Anetnne.jpeg",s="/aktivitaeten/bunkerfest2026/Torsten_DA6TW.jpeg",a="/aktivitaeten/bunkerfest2026/Yannick_DK8YS.jpg";const o={},g=t('<h1 id="wwbota-bunkerfest-2026" tabindex="-1"><a class="header-anchor" href="#wwbota-bunkerfest-2026" aria-hidden="true">#</a> WWBOTA-Bunkerfest 2026</h1><p>Heute stand f\xFCr Yannick <strong>DK8YS</strong> und mich, Torsten <strong>DA6TW</strong>, das <strong>WWBOTA-Bunkerfest 2026</strong> auf dem Programm.</p><p>Gegen 11:00 Uhr machten wir uns auf den Weg und waren etwa eine Stunde sp\xE4ter am QRV. Zum Einsatz kamen der Yaesu <strong>FT-891</strong> sowie eine <strong>15-m-T2LT-Antenne</strong> auf einem <strong>10-m-Mast</strong>.</p><p>Die Bedingungen waren an diesem Tag einfach hervorragend. Bereits innerhalb der ersten Stunde konnten wir <strong>30 QSOs</strong> ins Log bringen. Die Stationen kamen unter anderem aus <strong>England, Spanien, \xD6sterreich und Griechenland</strong>, dazu unz\xE4hlige Verbindungen innerhalb Deutschlands. Besonders der ausgepr\xE4gte Short-Skip sorgte f\xFCr viele starke Signale und machte richtig Spa\xDF. Wir waren von den Ausbreitungsbedingungen mehr als begeistert.</p><p>Zus\xE4tzlich konnten wir noch <strong>2 B2B-Kontakte (Bunker-to-Bunker)</strong> sowie <strong>6 P2P-Verbindungen (Park-to-Park)</strong> arbeiten, was die Aktivierung noch erfolgreicher machte.</p><p>Insgesamt war die Aktivierung ein voller Erfolg. Einschlie\xDFlich Auf- und Abbau waren wir nach rund vier Stunden wieder fertig und konnten mit einem zufriedenen Gef\xFChl die Heimreise antreten.</p><p><strong>Aktivierungen:</strong></p><p><strong>POTA</strong></p><ul><li>DE-0192 Saar Regional Park</li><li>DE-0693 Biosph\xE4re Bliesgau Biosphere Reserve</li></ul><p><strong>WWBOTA</strong></p><ul><li>B/DL-0824 WH 337 \u2013 Westwall Bunker B29</li></ul><p><strong>WWFF</strong></p><ul><li>DLFF-0033 \u2013 Nature Reserve / Biosph\xE4re Bliesgau</li></ul><p>Vielen Dank an alle Stationen f\xFCr die vielen sch\xF6nen QSOs. Bis zur n\xE4chsten Aktivierung \u2013 <strong>73!</strong></p><p><img src="'+i+'" alt=""><img src="'+s+'" alt=""><img src="'+a+'" alt=""></p>',15),u=[g];function l(d,c){return n(),r("div",null,u)}var p=e(o,[["render",l],["__file","2026-07-25-wwbota-bunkerfest-2026.html.vue"]]);export{p as default};
